PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('OWNER','LOGISTIK')),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,stock_full_open INTEGER NOT NULL DEFAULT 0,stock_empty_open INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS partners(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('CUSTOMER','SUPPLIER')),phone TEXT,address TEXT);
CREATE TABLE IF NOT EXISTS customer_prices(customer_id TEXT NOT NULL REFERENCES partners(id),product_id TEXT NOT NULL REFERENCES products(id),price INTEGER NOT NULL CHECK(price>=0),PRIMARY KEY(customer_id,product_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN('IN_FULL','OUT_FULL')),origin TEXT NOT NULL CHECK(origin IN('OWNER','LOGISTIK')),partner_id TEXT REFERENCES partners(id),product_id TEXT NOT NULL REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),empty_qty INTEGER NOT NULL DEFAULT 0 CHECK(empty_qty>=0),received_qty INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN('PENDING','PARTIAL','APPROVED','REJECTED')),reference TEXT,notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS financials(document_id TEXT PRIMARY KEY REFERENCES documents(id),price INTEGER NOT NULL CHECK(price>=0),paid INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,invoice_number TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_events(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),delta_full INTEGER NOT NULL DEFAULT 0,delta_empty INTEGER NOT NULL DEFAULT 0,qty INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS stock_event_document_once ON stock_events(document_id);
